writes:
{
  "name": "Beer distribution game",
  "brief": {
    "situation": "You run one company in a four-stage beer supply chain: a retailer, a wholesaler, a distributor and a factory, each run by an agent. Customers buy beer from the retailer every week. The product is a single brand of beer, measured in cases.",
    "rules": "The game lasts {$inputs.weeks} weeks. Each week runs in this order: first every company ships to the company below it, then every company orders from the company above it (the factory starts production instead of ordering). An order reaches the supplier the following week. Shipments take {$inputs.ship_lead} weeks to arrive and production takes {$inputs.prod_lead} weeks to arrive. Demand a company cannot fill becomes backlog and must be shipped later. At the end of every week each company pays {$inputs.holding_cost|money} per case in stock and {$inputs.backlog_cost|money} per case of backlog. Every company starts with {$inputs.start_stock} cases in stock and {$inputs.start_pipeline} cases on the way on each shipping link. You only ever see your own stock, backlog, incoming orders and incoming deliveries — never the other companies' positions. The team's goal is the lowest total cost.",
    "roles": {
      "company": "You run one company of the supply chain; your role is given in your position. Customers buy from the retailer. You ship to the company below you and order from the company above you (the factory starts production instead)."
    }
  },
  "clock": {"rounds": "$inputs.weeks", "unit": "week"},
  "inputs": {
    "weeks": {"type": "int", "default": 20, "min": 1, "description": "Number of weeks the game lasts"},
    "demand_min": {"type": "int", "default": 0, "min": 0, "description": "Lowest weekly customer demand"},
    "demand_max": {"type": "int", "default": 8, "min": 0, "description": "Highest weekly customer demand"},
    "start_stock": {"type": "int", "default": 12, "min": 0, "description": "Cases each company starts with in stock"},
    "start_pipeline": {"type": "int", "default": 4, "min": 0, "description": "Cases already on the way on each shipping link at the start"},
    "ship_lead": {"type": "int", "default": 2, "min": 0, "description": "Weeks a shipment takes to arrive"},
    "prod_lead": {"type": "int", "default": 2, "min": 0, "description": "Weeks production takes to arrive"},
    "holding_cost": {"type": "number", "default": 0.5, "min": 0, "description": "Cost per case in stock at the end of a week"},
    "backlog_cost": {"type": "number", "default": 1.0, "min": 0, "description": "Cost per case of backlog at the end of a week"},
    "max_order": {"type": "int", "default": 30, "min": 0, "description": "Largest order or production batch a company may place"}
  },
  "world": {
    "customer_demand": {"type": "list", "default": []},
    "factory_orders": {"type": "list", "default": []},
    "sold_to_customers": {"type": "int", "default": 0, "min": 0},
    "total_cost": {"type": "number", "default": 0.0, "min": 0}
  },
  "types": {
    "company": {
      "agent": true,
      "props": {
        "role": {"type": "text", "default": "retailer"},
        "upstream": {"type": "text", "default": ""},
        "downstream": {"type": "text", "default": ""},
        "stock": {"type": "int", "default": 0, "min": 0},
        "incoming": {"type": "int", "default": 0, "min": 0},
        "orders_in": {"type": "int", "default": 0, "min": 0},
        "ordered": {"type": "int", "default": 0, "min": 0},
        "backlog": {"type": "int", "default": 0, "min": 0},
        "production": {"type": "int", "default": 0, "min": 0},
        "shipped": {"type": "int", "default": 0, "min": 0},
        "received": {"type": "int", "default": 0, "min": 0},
        "cost": {"type": "number", "default": 0.0, "min": 0},
        "last_order": {"type": "int", "default": 0, "min": 0},
        "last_shipped": {"type": "int", "default": 0, "min": 0},
        "last_received": {"type": "int", "default": 0, "min": 0}
      }
    }
  },
  "population": [
    {
      "type": "company",
      "count": "$inputs.weeks",
      "id": "filler_{$i}",
      "name": "Filler {$i}",
      "props": {"role": "filler", "stock": 0, "incoming": 0}
    },
    {"type": "company", "count": 1, "id": "retailer", "name": "Retailer", "props": {"role": "retailer", "upstream": "wholesaler", "stock": "$inputs.start_stock", "incoming": "$inputs.start_pipeline"}},
    {"type": "company", "count": 1, "id": "wholesaler", "name": "Wholesaler", "props": {"role": "wholesaler", "upstream": "distributor", "downstream": "retailer", "stock": "$inputs.start_stock", "incoming": "$inputs.start_pipeline"}},
    {"type": "company", "count": 1, "id": "distributor", "name": "Distributor", "props": {"role": "distributor", "upstream": "factory", "downstream": "wholesaler", "stock": "$inputs.start_stock", "incoming": "$inputs.start_pipeline"}},
    {"type": "company", "count": 1, "id": "factory", "name": "Factory", "props": {"role": "factory", "downstream": "distributor", "stock": "$inputs.start_stock", "incoming": "$inputs.start_pipeline", "production": "$inputs.start_pipeline"}}
  ],
  "stages": [
    {
      "name": "shipping",
      "brief": "Ship beer to the company below you. If you owe backlog, ship at least that much whenever you can.",
      "actions": ["ship"],
      "turns": "sequential",
      "order": "$it.role == retailer and 0 or ($it.role == wholesaler and 1 or ($it.role == distributor and 2 or 3))",
      "who": "$it.role != filler and $it.role != factory",
      "max_actions": 1
    },
    {
      "name": "ordering",
      "brief": "Place your order with the company above you (the factory starts production instead). The order reaches them next week.",
      "actions": ["order"],
      "turns": "simultaneous",
      "who": "$it.role != filler",
      "max_actions": 1
    }
  ],
  "actions": {
    "ship": {
      "by": "company",
      "description": "Ship beer to the company below you this week. You must clear your whole backlog before shipping anything else, and you can never ship more than your backlog plus the orders you have received.",
      "params": {
        "amount": {"type": "int", "min": 0, "max": "$min($actor.stock + $actor.incoming, $actor.backlog + $actor.orders_in)", "description": "Cases to ship this week"}
      },
      "when": [
        "$actor.role != factory and $actor.role != filler",
        {"expr": "$actor.stock + $actor.incoming > 0", "why": "You have nothing to ship."},
        {"expr": "$params.amount >= $actor.backlog", "why": "You must clear your whole backlog before shipping anything else."},
        {"expr": "$params.amount <= $actor.stock + $actor.incoming", "why": "You do not have that much beer."},
        {"expr": "$params.amount <= $actor.backlog + $actor.orders_in", "why": "You cannot ship more than your backlog plus the orders you have received."}
      ],
      "do": [
        "$got = $min($actor.backlog + $actor.orders_in, $actor.stock + $actor.incoming)",
        "$actor.incoming -= $got",
        "$actor.stock -= $got",
        "$actor.shipped += $got",
        "$actor.last_shipped = $got",
        "$actor.backlog = $actor.backlog + $actor.orders_in - $got",
        "$actor.orders_in = 0",
        {"if": "$actor.downstream != ''", "then": ["$entity($actor.downstream).incoming += $got"], "else": ["$world.sold_to_customers += $got"]}
      ],
      "outcome": "You shipped {$got} cases to the company below you.",
      "private": true
    },
    "order": {
      "by": "company",
      "description": "Order beer from the company above you (the factory starts production instead). The order reaches them next week.",
      "params": {
        "amount": {"type": "int", "min": 0, "max": "$inputs.max_order", "description": "Cases to order from your supplier"}
      },
      "when": [
        "$actor.role != filler"
      ],
      "do": [
        "$actor.last_order = $params.amount,
        {"if": "$actor.role == factory", "then": ["$world.factory_orders += $params.amount", "$actor.production += $params.amount"], "else": ["$entity($actor.upstream).ordered += $params.amount"]}
      ],
      "outcome": "You ordered {$params.amount} cases from your supplier.",
      "private": true
    }
  },
  "events": [
    {
      "name": "customer demand",
      "phase": "start",
      "do": [
        "$world.customer_demand += $randint($inputs.demand_min, $inputs.demand_max)",
        "$ret = $entity(retailer)",
        "$ret.orders_in += $last($world.customer_demand)"
      ],
      "say": "Customers order {$last($world.customer_demand)} cases of beer from the retailer this week."
    },
    {
      "name": "deliveries",
      "phase": "start",
      "each": "$filter(company, $it.role != filler)",
      "do": [
        "$d = $it.incoming",
        "$it.incoming = 0",
        "$it.stock += $d",
        "$it.received += $d",
        "$it.last_received = $d",
        "$it.incoming = $it.production",
        "$it.production = 0"
      ],
      "say": "Deliveries arrive."
    },
    {
      "name": "orders reach suppliers",
      "phase": "end",
      "each": "$filter(company, $it.role != filler and $it.role != factory)",
      "do": ["$it.orders_in += $it.ordered", "$it.ordered = 0"],
      "say": "Orders reach the suppliers."
    },
    {
      "name": "weekly costs",
      "phase": "end",
      "each": "$filter(company, $it.role != filler)",
      "do": [
        "$it.cost += $it.stock * $inputs.holding_cost + $it.backlog * $inputs.backlog_cost",
        "$world.total_cost += $it.stock * $inputs.holding_cost + $it.backlog * $inputs.backlog_cost"
      ]
    }
  ],
  "metrics": {
    "customer_demand": {"expr": "$last($world.customer_demand)", "description": "Customer demand this week"},
    "factory_orders": {"expr": "$last($world.factory_orders)", "description": "Factory production orders this week"},
    "total_cost": {"expr": "$world.total_cost", "unit": "$"}
  },
  "views": {
    "position": {
      "title": "Your position",
      "show": "It is week {$round} of {$inputs.weeks}. You are the {$actor.role}: stock {stock} cases, backlog {backlog} cases, orders waiting to be shipped {orders_in} cases, cost so far {$actor.cost|money}."
    },
    "arrivals": {
      "title": "This week",
      "show": "Arrived: {last_received} cases. Shipped: {last_shipped} cases. Last order you placed: {last_order} cases."
    },
    "pipeline": {
      "title": "On the way to you",
      "show": "{incoming} cases are on the way to you (production included, if you are the factory)."
    },
    "chain": {
      "for": "spectator",
      "of": "company",
      "title": "Supply chain",
      "where": "$it.role != filler",
      "show": "{role}: stock {stock}, backlog {backlog}, incoming {incoming}, orders_in {orders_in}, production {production}, cost {$it.cost|money}"
    }
  },
  "outputs": {
    "customer_demand": {"expr": "$world.customer_demand", "type": "list", "description": "Cases customers demanded each week, in week order"},
    "factory_orders": {"expr": "$world.factory_orders", "type": "list", "description": "Cases the factory put into production each week, in week order"},
    "costs_by_role": {"expr": "$dict(company, $it.role, $it.cost)", "type": "map", "description": "Total cost of each company, by role"},
    "total_team_cost": {"expr": "$world.total_cost", "type": "number", "format": "money", "description": "Sum of all four companies' costs"},
    "bullwhip_ratio": {"expr": "$variance($series.factory_orders) / $variance($series.customer_demand)", "type": "number", "description": "Variance of the factory's weekly production orders divided by the variance of weekly customer demand"}
  },
  "invariants": [
    {"expr": "$count(company, $it.role != filler) == 4", "why": "The supply chain has exactly four companies."},
    {"expr": "$all(company, $it.stock >= 0 and $it.backlog >= 0 and $it.incoming >= 0 and $it.production >= 0 and $it.cost >= 0)", "why": "Stocks, backlogs and costs are never negative."},
    {"expr": "$sum(company, $it.stock + $it.incoming + $it.production) + $world.sold_to_customers == $inputs.start_stock * 4 + $inputs.start_pipeline * 5 + $sum($world.factory_orders)", "why": "Beer is conserved: everything shipped or produced is in stock, in transit or delivered to customers."}
  ]
}
